const input = $input.first()?.json ?? {};
const originalUpdate = (input && typeof input === 'object') ? input : {};
const message = (originalUpdate.message && typeof originalUpdate.message === 'object') ? originalUpdate.message : null;
const callback = (originalUpdate.callback_query && typeof originalUpdate.callback_query === 'object') ? originalUpdate.callback_query : null;
const callbackMessage = (callback?.message && typeof callback.message === 'object') ? callback.message : null;
const effectiveMessage = message ?? callbackMessage;
const from = (message?.from && typeof message.from === 'object') ? message.from : ((callback?.from && typeof callback.from === 'object') ? callback.from : {});
const chat = (effectiveMessage?.chat && typeof effectiveMessage.chat === 'object') ? effectiveMessage.chat : {};
return [{ json: {
  original_update: originalUpdate,
  normalized: {
    update_id: typeof originalUpdate.update_id === 'number' ? originalUpdate.update_id : 0,
    chat_id: typeof chat.id === 'number' ? chat.id : 0,
    user_id: typeof from.id === 'number' ? from.id : 0,
    message_id: typeof effectiveMessage?.message_id === 'number' ? effectiveMessage.message_id : 0,
    message_text: typeof message?.text === 'string' ? message.text : '',
    callback_query_id: typeof callback?.id === 'string' ? callback.id : '',
    callback_data: typeof callback?.data === 'string' ? callback.data : '',
    language_code: typeof from.language_code === 'string' ? from.language_code : '',
    display_name: [from.first_name, from.last_name].filter(v => typeof v === 'string' && v.length > 0).join(' ')
  }
} }];

const data = $input.first()?.json ?? {};
const n = (data.normalized && typeof data.normalized === 'object') ? data.normalized : {};
const receivedAt = new Date().toISOString();
return [{ json: {
  original_update: (data.original_update && typeof data.original_update === 'object') ? data.original_update : {},
  gateway_context: {
    schema_version: '1.0', gateway_version: '1.0', source: 'telegram',
    telegram: {
      update_id: typeof n.update_id === 'number' ? n.update_id : 0,
      chat_id: typeof n.chat_id === 'number' ? n.chat_id : 0,
      user_id: typeof n.user_id === 'number' ? n.user_id : 0,
      message_id: typeof n.message_id === 'number' ? n.message_id : 0,
      message_text: typeof n.message_text === 'string' ? n.message_text : '',
      callback_query_id: typeof n.callback_query_id === 'string' ? n.callback_query_id : '',
      callback_data: typeof n.callback_data === 'string' ? n.callback_data : '',
      language_code: typeof n.language_code === 'string' ? n.language_code : ''
    },
    user: { portal_user_id: '', display_name: typeof n.display_name === 'string' ? n.display_name : '', locale: 'zh-TW' },
    route: { domain: '', action: '', target_workflow: '' }, received_at: receivedAt
  }
} }];

const data = $input.first()?.json ?? {};
const update = (data.original_update && typeof data.original_update === 'object') ? data.original_update : {};
const hasCallback = !!(update.callback_query && typeof update.callback_query === 'object');
const hasMessage = !!(update.message && typeof update.message === 'object');
return [{ json: { ...data, detection: { update_type: hasCallback ? 'callback_query' : (hasMessage ? 'message' : 'unsupported') } } }];

const data = $input.first()?.json ?? {};
const ctx = (data.gateway_context && typeof data.gateway_context === 'object') ? data.gateway_context : {};
const tg = (ctx.telegram && typeof ctx.telegram === 'object') ? ctx.telegram : {};
const text = typeof tg.message_text === 'string' ? tg.message_text : '';
const match = text.match(/^\s*\/([A-Za-z0-9_]+)(?:@([A-Za-z0-9_]+))?(?=\s|$)/);
let command = { detected: false, name: '', bot_username: '', raw_text: text, arguments: [] };
if (match) {
  const rest = text.slice(match[0].length).trim();
  const parsed = [];
  const tokenPattern = /"((?:\\.|[^"\\])*)"|'((?:\\.|[^'\\])*)'|(\S+)/g;
  let token;
  while ((token = tokenPattern.exec(rest)) !== null) {
    const value = token[1] ?? token[2] ?? token[3] ?? '';
    parsed.push(value.replace(/\\([\\"'])/g, '$1'));
  }
  command = { detected: true, name: String(match[1] ?? '').toLowerCase(), bot_username: String(match[2] ?? ''), raw_text: text, arguments: parsed };
}
return [{ json: { ...data, detection: { ...(data.detection ?? {}), command } } }];

const data = $input.first()?.json ?? {};
const ctx = (data.gateway_context && typeof data.gateway_context === 'object') ? data.gateway_context : {};
const tg = (ctx.telegram && typeof ctx.telegram === 'object') ? ctx.telegram : {};
const raw = typeof tg.callback_data === 'string' ? tg.callback_data : '';
const parts = raw.split(':');
const prefix = parts.length > 1 ? String(parts[0] ?? '').toLowerCase() : '';
const action = parts.length > 1 ? parts.slice(1).join(':') : '';
const allowed = ['portal', 'social', 'novel', 'admin'];
const callback = { detected: raw.length > 0 && allowed.includes(prefix) && action.length > 0, prefix, action, raw_data: raw };
return [{ json: { ...data, detection: { ...(data.detection ?? {}), callback } } }];

const data = $input.first()?.json ?? {};
const detection = (data.detection && typeof data.detection === 'object') ? data.detection : {};
const callback = (detection.callback && typeof detection.callback === 'object') ? detection.callback : {};
const command = (detection.command && typeof detection.command === 'object') ? detection.command : {};
const portalCommands = new Set(['start', 'menu', 'back']);
const novelCommands = new Set(['new', 'chapter', 'novel', 'storybible']);
const socialCommands = new Set(['publish', 'results', 'socialstatus']);
const adminCommands = new Set(['system', 'health']);
let domain = 'portal', action = 'fallback', target = 'portal.fallback', branch = 'fallback';
if (callback.detected === true) {
  domain = String(callback.prefix ?? 'portal'); action = String(callback.action ?? 'fallback');
  if (domain === 'social') { target = 'TG-100'; branch = 'social'; }
  else if (domain === 'novel' && ['new', 'chapter'].includes(action)) { target = 'WF-000'; branch = 'novel'; }
  else if (domain === 'novel') { target = ''; branch = 'fallback'; }
  else if (domain === 'admin') { target = 'admin.route'; branch = 'admin'; }
  else { target = action.startsWith('planned:') ? 'portal.planned' : 'portal.menu'; branch = 'portal'; }
} else if (command.detected === true) {
  const name = String(command.name ?? ''); action = name || 'fallback';
  if (portalCommands.has(name)) { domain = 'portal'; action = name === 'back' ? 'back' : 'menu'; target = 'portal.menu'; branch = 'portal'; }
  else if (name === 'novel') { domain = 'social'; action = 'novel'; target = 'TG-100'; branch = 'social'; }
  else if (novelCommands.has(name)) { domain = 'novel'; target = ['new', 'chapter'].includes(name) ? 'WF-000' : ''; branch = ['new', 'chapter'].includes(name) ? 'novel' : 'fallback'; }
  else if (socialCommands.has(name)) { domain = 'social'; target = 'TG-100'; branch = 'social'; }
  else if (adminCommands.has(name)) { domain = 'admin'; target = 'admin.route'; branch = 'admin'; }
} 
const ctx = (data.gateway_context && typeof data.gateway_context === 'object') ? data.gateway_context : {};
return [{ json: { ...data, gateway_context: { ...ctx, route: { domain, action, target_workflow: target } }, route_branch: branch } }];

