const action = typeof ctx.route?.action === 'string' ? ctx.route.action : '';
const args = commandDetected && Array.isArray(detection.command?.arguments) ? detection.command.arguments : [];
const rawText = commandDetected && typeof detection.command?.raw_text === 'string' ? detection.command.raw_text : '';
return [{ json: {
  schema_version: '1.0', workflow_version: '2.0', route: `command.${action}`, target: 'WF-000', status: 'ready', is_valid: true, validation_errors: [],
  command: { name: action, arguments: args, raw_text: rawText },
  context: { telegram_update_id: typeof tg.update_id === 'number' ? tg.update_id : 0, telegram_chat_id: typeof tg.chat_id === 'number' ? tg.chat_id : 0, telegram_user_id: typeof tg.user_id === 'number' ? tg.user_id : 0, received_at: typeof ctx.received_at === 'string' ? ctx.received_at : '' },
  gateway_context: ctx, original_update: (data.original_update && typeof data.original_update === 'object') ? data.original_update : {}, dispatch_metadata: { domain: 'novel', action, target_workflow: 'WF-000' }
} }];

const data = $input.first()?.json ?? {};
const ctx = (data.gateway_context && typeof data.gateway_context === 'object') ? data.gateway_context : {};
