const data = $input.first()?.json ?? {};
const menu = { text: '📚 Novel Studio\n\n請選擇功能：', inline_keyboard: [[{ text: '➕ 新增小說', callback_data: 'novel_create' }], [{ text: '📖 選擇小說', callback_data: 'novel_select' }], [{ text: '📝 建立章節', callback_data: 'chapter_create' }], [{ text: '✍️ 寫作章節', callback_data: 'chapter_write' }], [{ text: '📊 小說狀態', callback_data: 'novel_status' }], [{ text: '⬅ 返回社群中心', callback_data: 'social_home' }]] };
