return [{ json: { ...data, branch_result: { kind: unsupportedNovel ? 'supported_not_implemented' : 'fallback', status: 'ready', is_valid: true, message: unsupportedNovel ? '此 Novel Studio 功能尚未實作。' : '', menu } } }];

const data = $input.first()?.json ?? {};
const inferredNovel = !!(data.integration && typeof data.integration === 'object' && data.context && typeof data.context === 'object');
const suppliedContext = (data.gateway_context && typeof data.gateway_context === 'object') ? data.gateway_context : {};
const ctx = inferredNovel && !suppliedContext.route ? { received_at: '', route: { domain: 'novel', action: String(data.route ?? '').includes('chapter') ? 'chapter' : 'new', target_workflow: 'WF-000' }, telegram: { update_id: Number(data.context.telegram_update_id ?? 0), chat_id: Number(data.context.telegram_chat_id ?? 0), user_id: Number(data.context.telegram_user_id ?? 0) }, user: { portal_user_id: '', display_name: '', locale: 'zh-TW' } } : suppliedContext;
const route = (ctx.route && typeof ctx.route === 'object') ? ctx.route : {};
const branch = (data.branch_result && typeof data.branch_result === 'object') ? data.branch_result : null;
const dispatch = (data.dispatch_metadata && typeof data.dispatch_metadata === 'object') ? data.dispatch_metadata : (inferredNovel ? { domain: 'novel', action: route.action ?? '', target_workflow: 'WF-000' } : ((route.domain === 'social' || route.domain === 'novel') ? { domain: route.domain, action: route.action ?? '', target_workflow: route.target_workflow ?? '' } : null));
const telegram = (ctx.telegram && typeof ctx.telegram === 'object') ? ctx.telegram : {};
const user = (ctx.user && typeof ctx.user === 'object') ? ctx.user : {};
const completedAt = new Date().toISOString();
if (branch) {
  const isMenu = branch.kind === 'menu';
  return [{ json: { schema_version:'1.0', gateway_version:'1.0', route:isMenu?'gateway.menu':'gateway.ready', status:'ready', is_valid:true, validation_errors:[], gateway:{domain:route.domain ?? 'portal',action:route.action ?? (isMenu?'menu':'fallback'),target_workflow:route.target_workflow ?? '',dispatched:false,received_at:ctx.received_at ?? '',completed_at:completedAt}, ...(branch.menu?{menu:branch.menu}:{}), ...(branch.message?{message:branch.message}:{}), result:branch, telegram, user } }];
}
const validSubworkflowResult = data && typeof data === 'object' && data.is_valid === true && data.status === 'ready' && data.response && typeof data.response === 'object' && typeof data.response.type === 'string' && data.response.type.trim().length > 0;
if (validSubworkflowResult) {
  const social = (data.social && typeof data.social === 'object') ? data.social : null;
  return [{ json: { schema_version:'1.0',gateway_version:'1.0',route:data.route,status:'ready',is_valid:true,validation_errors:data.validation_errors ?? [],gateway:{domain:social?'social':(dispatch?.domain ?? route.domain ?? ''),action:social?(social.action ?? route.action ?? ''):(dispatch?.action ?? route.action ?? ''),target_workflow:social?'TG-100':(dispatch?.target_workflow ?? route.target_workflow ?? ''),dispatched:true,failed_stage:''},result:data,response:data.response,telegram,user } }];
}
const errorLike = data.error ?? data.executionError ?? null;
if (!dispatch || errorLike) {
  return [{ json: { schema_version:'1.0',gateway_version:'1.0',route:'gateway.failed',status:'error',is_valid:false,validation_errors:[{code:'SUBWORKFLOW_UNBOUND_OR_FAILED',message:'目標子工作流程未綁定或執行失敗。'}],gateway:{domain:route.domain ?? '',action:route.action ?? '',target_workflow:route.target_workflow ?? '',dispatched:false,failed_stage:'subworkflow_dispatch'},result:null,telegram,user } }];
}
return [{ json: { schema_version:'1.0',gateway_version:'1.0',route:'gateway.dispatched',status:'ready',is_valid:true,validation_errors:[],gateway:{domain:dispatch.domain ?? route.domain ?? '',action:dispatch.action ?? route.action ?? '',target_workflow:dispatch.target_workflow ?? route.target_workflow ?? '',dispatched:true,received_at:ctx.received_at ?? '',completed_at:completedAt},result:data,telegram,user } }];

const data = $input.first()?.json ?? {};
const gateway = (data.gateway && typeof data.gateway === 'object') ? data.gateway : {};
const telegram = (data.telegram && typeof data.telegram === 'object') ? data.telegram : {};
return [{ json: { ...data, audit_context: { persistence: 'none', gateway_version: '1.0', domain: typeof gateway.domain === 'string' ? gateway.domain : '', action: typeof gateway.action === 'string' ? gateway.action : '', update_id: typeof telegram.update_id === 'number' ? telegram.update_id : 0, completed_at: typeof gateway.completed_at === 'string' ? gateway.completed_at : new Date().toISOString() } } }];

const data = $input.first()?.json ?? {};
const result = (data.result && typeof data.result === 'object') ? data.result : {};
const response = (result.response && typeof result.response === 'object') ? result.response : null;
if (!response) return [];
const type = typeof response.type === 'string' ? response.type : '';
if (!['telegram_menu', 'telegram_message'].includes(type)) return [];
const telegram =
  data.telegram && typeof data.telegram === 'object'
    ? data.telegram
    : {};
const inlineKeyboard = type === 'telegram_menu' && Array.isArray(response.inline_keyboard) ? response.inline_keyboard : [];
return [{ json: { ...data, telegram_response: { chat_id: Number(telegram.chat_id ?? 0), text: typeof response.text === 'string' ? response.text : '', inline_keyboard: inlineKeyboard } } }];
